49	export function AddFunds() {
50	  const [amount, setAmount] = useState<string>("25");
51	  const [busy, setBusy] = useState(false);
52	  const [error, setError] = useState<string | null>(null);
53	  const [demoMode, setDemoMode] = useState(false);
54	  const [session, setSession] = useState<{ clientSecret: string; publishableKey: string } | null>(null);
55	
56	  if (demoMode) return <DemoTopUp />;
57	
58	  const checkout = async () => {
59	    setBusy(true);
60	    setError(null);
61	    try {
62	      const res = await fetch("/api/stripe/checkout", {
63	        method: "POST",
64	        headers: { "Content-Type": "application/json" },
65	        body: JSON.stringify({ amount: Number(amount) }),
66	      });
67	      const json: { clientSecret?: string; publishableKey?: string; error?: string } = await res
68	        .json()
69	        .catch(() => ({}));
70	      if (json.clientSecret && json.publishableKey) {
71	        // Pay in the embedded modal on THIS page — no redirect to Stripe.
72	        setSession({ clientSecret: json.clientSecret, publishableKey: json.publishableKey });
73	        setBusy(false);
74	        return;
75	      }
76	      const msg = json.error ?? "Checkout failed — try again.";
77	      if (msg.toLowerCase().includes("not configured")) {
78	        setDemoMode(true);
79	      } else {
80	        setError(msg);
81	      }
82	    } catch {
83	      setError("Network error — try again.");
84	    }
85	    setBusy(false);
86	  };
87	
88	  const n = Number(amount);
89	  const valid = Number.isFinite(n) && n >= 5 && n <= 5000;
90	
91	  return (
92	    <div>
93	      <div className="flex flex-wrap items-end gap-3">
94	        <div>
95	          <label className="label">Amount (USD)</label>
96	          <div className="flex items-center gap-2">
97	            {PRESETS.map((p) => (
98	              <button
99	                key={p}
100	                type="button"
101	                onClick={() => setAmount(String(p))}
102	                className={`chip h-[30px] px-3 text-[12px] ${amount === String(p) ? "chip-on" : ""}`}
103	              >
104	                ${p}
105	              </button>
106	            ))}
107	            <input
108	              className="input w-28"
109	              type="number"
110	              min={5}
111	              max={5000}
112	              value={amount}
113	              onChange={(e) => setAmount(e.target.value)}
114	            />
115	          </div>
116	        </div>
117	        <button className="btn-primary" onClick={() => void checkout()} disabled={busy || !valid}>
118	          {busy ? "Loading…" : "Add funds"}
119	        </button>
120	      </div>
121	      {!valid && amount !== "" && (
122	        <p className="mt-2 text-xs text-amber-300">Amount must be between $5 and $5000.</p>
123	      )}
124	      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
125	      <p className="mt-2 text-xs text-slate-500">Secure card checkout powered by Stripe.</p>
126	      {session && (
127	        <AddFundsPaymentModal
128	          clientSecret={session.clientSecret}
129	          publishableKey={session.publishableKey}
130	          amountCents={Math.round(n * 100)}
131	          onClose={() => setSession(null)}
132	        />
133	      )}
134	    </div>
135	  );
