137	/* One of the small figure cards the concept opens each page with: a number, a
138	   label, and a mark. Kept here so billing, support and activity cannot each
139	   invent their own version. */
140	export function StatCard({
141	  icon, value, label, foot, tone = "blue", volatileValue, bareIcon,
142	}: {
143	  icon: string; value: string; label: string; foot?: React.ReactNode;
144	  tone?: "blue" | "mint" | "amber" | "violet";
145	  /** Set when `value` is derived from the reader's locale or clock (a formatted
146	      date, a "3 days" countdown). Those legitimately differ between the server
147	      render and the browser's, and React tears the tree down over it unless it
148	      is told the difference is expected. */
149	  volatileValue?: boolean;
150	  /** No bordered plate behind the mark, and a larger mark so it still reads as
151	   *  intentional without one. Sized against the value's cap height rather than
152	   *  the whole text block — the first pass doubled it to 34 (51px after
153	   *  ICON_SCALE), which was about 2.4x the number beside it and read as
154	   *  oversized on every page that uses these. */
155	  bareIcon?: boolean;
156	}) {
157	  const ring = tone === "mint" ? "rgba(17,200,142,0.30)"
158	             : tone === "amber" ? "rgba(240,180,60,0.30)"
159	             : tone === "violet" ? "rgba(147,51,255,0.32)"
160	             : "rgba(47,126,239,0.32)";
161	  return (
162	    // `min-h` so a card with a `foot` line (an extra line of text under the
163	    // label) doesn't render visibly taller than its foot-less siblings in
164	    // the same stat row — every consumer mixes the two (Support's "Avg
165	    // response time" card only grows a foot when there's no data yet).
166	    <section className="card flex min-h-[88px] min-w-0 items-start gap-3 p-3.5">
167	      {bareIcon ? (
168	        <Icon name={icon} size={24} />
169	      ) : (
170	        <span className="grid h-[42px] w-[42px] flex-none place-items-center rounded-[11px] border border-rim-hi"
171	              style={{ background: "linear-gradient(180deg, rgba(24,74,180,0.55), rgba(4,20,60,0.9))", boxShadow: `inset 0 0 0 1px ${ring}` }}>
172	          <Icon name={icon} size={17} />
173	        </span>
174	      )}
175	      <span className="flex min-w-0 flex-col gap-0.5">
176	        <span suppressHydrationWarning={volatileValue} className="num text-[23px] leading-none text-white">{value}</span>
177	        <span className="text-[11.5px] text-tx-dim">{label}</span>
178	        {foot}
179	      </span>
180	    </section>
181	  );
182	}
