// Ad-hoc audit script for agent B's assigned pages (billing, invoices, affiliate,
// partner, team, feedback, whats-new). Screenshots both dark (default) and light
// theme. Deleted when the audit is done, per repo convention.
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";
import { join } from "node:path";

const BASE = process.env.BASE_URL || "https://v2.q4w8zt3ky6vn2sm.nxeon.cloud";
const EMAIL = process.env.NX_EMAIL || "customer@nxeon.local";
const PASS = process.env.NX_PASS || "wGPZqhCbsLdz";
const out = process.argv[2] || "/tmp/audit-b";
mkdirSync(out, { recursive: true });

const PAGES = [
  "/dashboard/billing",
  "/dashboard/invoices",
  "/dashboard/affiliate",
  "/dashboard/partner",
  "/dashboard/team",
  "/dashboard/feedback",
  "/dashboard/whats-new",
];

const browser = await chromium.launch();

async function run(theme) {
  const ctx = await browser.newContext({ viewport: { width: 1600, height: 1100 }, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  await page.goto(`${BASE}/login`, { waitUntil: "domcontentloaded" });
  await page.fill('input[type="email"], input[name="email"]', EMAIL);
  await page.fill('input[type="password"], input[name="password"]', PASS);
  await Promise.all([
    page.waitForURL((u) => !u.pathname.includes("/login"), { timeout: 45000 }).catch(() => {}),
    page.click("button.btn-primary"),
  ]);

  if (theme === "light") {
    await page.evaluate(() => {
      localStorage.setItem("nx-theme", "light");
      document.documentElement.setAttribute("data-theme", "light");
    });
  }

  for (const p of PAGES) {
    const slug = p.replace(/^\//, "").replace(/[^a-z0-9]+/gi, "-") || "root";
    try {
      await page.goto(`${BASE}${p}`, { waitUntil: "networkidle", timeout: 60000 });
    } catch {
      await page.waitForTimeout(3000);
    }
    if (theme === "light") {
      await page.evaluate(() => document.documentElement.setAttribute("data-theme", "light"));
    }
    await page.waitForTimeout(2000);
    const file = join(out, `${slug}-${theme}.png`);
    await page.screenshot({ path: file, fullPage: true });
    console.log(`${theme} ${p} -> ${file}`);
  }

  // Billing: open settings tab (Add funds / Redeem / Auto top-up) and the card carousel add-card flow.
  await page.goto(`${BASE}/dashboard/billing`, { waitUntil: "networkidle", timeout: 60000 }).catch(() => {});
  if (theme === "light") await page.evaluate(() => document.documentElement.setAttribute("data-theme", "light"));
  await page.waitForTimeout(1500);
  const settingsTab = page.getByRole("button", { name: "Billing settings" });
  if (await settingsTab.count()) {
    await settingsTab.click();
    await page.waitForTimeout(1000);
    await page.screenshot({ path: join(out, `billing-settings-${theme}.png`), fullPage: true });
  }

  // Team: open invite modal.
  await page.goto(`${BASE}/dashboard/team`, { waitUntil: "networkidle", timeout: 60000 }).catch(() => {});
  if (theme === "light") await page.evaluate(() => document.documentElement.setAttribute("data-theme", "light"));
  await page.waitForTimeout(1500);
  const inviteBtn = page.getByRole("button", { name: "Invite Member" });
  if (await inviteBtn.count()) {
    await inviteBtn.click();
    await page.waitForTimeout(800);
    await page.screenshot({ path: join(out, `team-invite-modal-${theme}.png`), fullPage: true });
  }

  await ctx.close();
}

await run("dark");
await run("light");
await browser.close();

