1	"use client";
2	
3	/**
4	 * "Add a card" popup — styled and built exactly like AddFundsPaymentModal
5	 * (the same CheckoutElementsProvider + PaymentElement + STRIPE_APPEARANCE/
6	 * STRIPE_FONTS PaymentStep.tsx uses everywhere else), instead of the old
7	 * `StripeCheckoutModal`'s `<EmbeddedCheckout>` — Stripe's own prebuilt
8	 * light-themed page, which is exactly why saving a card looked like an
9	 * unstyled Stripe form dropped into a dark app. Every other Stripe surface
10	 * on this platform (orders, wallet top-up, outstanding-balance settle) was
11	 * already migrated off that; card setup was the one left behind.
12	 *
13	 * `createCardSetupSession` (lib/stripe-cards.ts) now opens the session with
14	 * `ui_mode: "elements"` instead of `"embedded_page"` — server-side that's a
15	 * one-line change, everything about `finalizeCardSetup`/`saveCardFromSetupSession`
16	 * is untouched. This component is the client-side half of that same move.
17	 */
18	
19	import { useMemo, useState } from "react";
20	import { createPortal } from "react-dom";
21	import {
22	  CheckoutElementsProvider,
23	  useCheckoutElements,
24	  PaymentElement,
25	} from "@stripe/react-stripe-js/checkout";
26	import { currentStripeAppearance, STRIPE_FONTS, stripeFor } from "@/components/customer/PaymentStep";
27	
28	function LockIcon({ className = "h-3.5 w-3.5" }: { className?: string }) {
29	  return (
30	    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" className={className}>
31	      <rect x="5" y="10.5" width="14" height="9" rx="1.7" />
32	      <path d="M8 10.5V7.5a4 4 0 0 1 8 0v3" />
33	    </svg>
34	  );
35	}
36	
37	/** Renders inside `<CheckoutElementsProvider>` — the only place `useCheckoutElements()` is valid. */
38	function CardSetupForm() {
39	  const checkoutState = useCheckoutElements();
40	  const checkoutActions = checkoutState.type === "success" ? checkoutState.checkout : undefined;
41	  const [confirming, setConfirming] = useState(false);
42	  const [error, setError] = useState<string | null>(null);
43	
44	  async function save() {
45	    if (!checkoutActions) return;
46	    setError(null);
47	    setConfirming(true);
48	    try {
49	      const result = await checkoutActions.confirm();
50	      if (result.type === "error") setError(result.error.message ?? "We couldn't save that card. Please try another.");
51	      // On success Stripe navigates the browser to the session's return_url —
52	      // the same /dashboard/billing?card_setup=<id> return leg
53	      // CardSetupReturn already handles.
54	    } catch {
55	      setError("Something went wrong saving your card. Please try again.");
56	    } finally {
57	      setConfirming(false);
58	    }
