import { chromium } from "playwright";
import { mkdirSync } from "node:fs";
import { join } from "node:path";

const BASE = "https://v2.q4w8zt3ky6vn2sm.nxeon.cloud";
const out = "/tmp/audit-b";
mkdirSync(out, { recursive: true });

const PAGES = [
  "/dashboard/billing",
  "/dashboard/invoices",
  "/dashboard/affiliate",
  "/dashboard/partner",
  "/dashboard/team",
  "/dashboard/feedback",
  "/dashboard/whats-new",
];

const browser = await chromium.launch();

async function run(theme) {
  const ctx = await browser.newContext({ viewport: { width: 1600, height: 1100 } });
  const page = await ctx.newPage();
  await page.goto(`${BASE}/login`, { waitUntil: "domcontentloaded" });
  await page.waitForTimeout(800);
  await page.fill('input[type="email"], input[name="email"]', "customer@nxeon.local");
  await page.fill('input[type="password"], input[name="password"]', "wGPZqhCbsLdz");
  await page.getByRole("button", { name: "Sign in" }).click();
  await page.waitForTimeout(2500);
  if (page.url().includes("/login")) {
    console.log(`LOGIN STILL FAILING (theme=${theme}), url=${page.url()}`);
    await ctx.close();
    return false;
  }
  if (theme === "light") {
    await page.evaluate(() => {
      localStorage.setItem("nx-theme", "light");
      document.documentElement.setAttribute("data-theme", "light");
    });
  }
  for (const p of PAGES) {
    const slug = p.replace(/^\//, "").replace(/[^a-z0-9]+/gi, "-") || "root";
    try {
      await page.goto(`${BASE}${p}`, { waitUntil: "networkidle", timeout: 60000 });
    } catch {
      await page.waitForTimeout(3000);
    }
    if (theme === "light") await page.evaluate(() => document.documentElement.setAttribute("data-theme", "light"));
    await page.waitForTimeout(1800);
    await page.screenshot({ path: join(out, `${slug}-${theme}.png`), fullPage: true });
    console.log(`${theme} ${p} OK`);
  }
  await ctx.close();
  return true;
}

const okDark = await run("dark");
const okLight = okDark ? await run("light") : false;
console.log("RESULT", { okDark, okLight });
await browser.close();

